#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    long long k;
    cin >> h >> w >> k;
    vector<vector<long long>> a(h, vector<long long>(w));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cin >> a[i][j];
        }
    }

    const long long MOD = 1000000007;
    int kk = (int)k;
    vector<vector<vector<long long>>> ways(h, vector<vector<long long>>(w, vector<long long>(kk, 0)));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int v = (int)(a[i][j] % kk);
            if (i == 0 && j == 0) { ways[0][0][v] = 1; continue; }
            for (int r = 0; r < kk; r++) {
                long long total = 0;
                if (i > 0) total += ways[i - 1][j][r];
                if (j > 0) total += ways[i][j - 1][r];
                int idx = (r + v) % kk;
                ways[i][j][idx] = (ways[i][j][idx] + total) % MOD;
            }
        }
    }
    cout << ways[h - 1][w - 1][0] << "\n";

    return 0;
}

