import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[][] a = new long[(int) h][(int) w];
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                a[i][j] = Long.parseLong(next());
            }
        }

        final long MOD = 1000000007L;
        int rowsCount = (int) h, colsCount = (int) w, kk = (int) k;
        long[][][] ways = new long[rowsCount][colsCount][kk];
        for (int i = 0; i < rowsCount; i++) {
            for (int j = 0; j < colsCount; j++) {
                int v = (int) (a[i][j] % kk);
                if (i == 0 && j == 0) { ways[0][0][v] = 1; continue; }
                for (int r = 0; r < kk; r++) {
                    long total = 0;
                    if (i > 0) total += ways[i - 1][j][r];
                    if (j > 0) total += ways[i][j - 1][r];
                    int idx = (r + v) % kk;
                    ways[i][j][idx] = (ways[i][j][idx] + total) % MOD;
                }
            }
        }
        System.out.println(ways[rowsCount - 1][colsCount - 1][0]);
    }
}
